import {BottomDeepWorkOwner,BOTTOM_DEEP_WORK_OWNER,BOTTOM_DEEP_WORK_CONTRACT,BOTTOM_DEEP_WORK_LIFECYCLE_POLICY} from './foundation/global/bottom-shelf.js';
import {validateBottomDeepWorkProvider} from './foundation/global/bottom-provider-contract.js';
import {StructuredBottomProvider} from './adapters/structured-bottom-provider.js';
import {OperationalBottomProvider} from './adapters/operational-bottom-provider.js';
import {createStructuredConsumerAdapter} from './adapters/structured-documents.js';
import {W03V34RunsAdapter} from './adapters/w03-runs.js';

const assert=(value,message='assertion failed')=>{if(!value)throw Error(message)};
const same=(a,b)=>JSON.stringify(a)===JSON.stringify(b);
const throws=(fn,token)=>{let message='';try{fn()}catch(error){message=String(error?.message||error)}assert(message.includes(token),`expected ${token}, got ${message}`)};
const test=(tests,id,run)=>{try{run();tests.push({id,status:'PASS'})}catch(error){tests.push({id,status:'FAIL',error:String(error?.message||error)})}};

function fixture(){
  const structured=createStructuredConsumerAdapter('learn');
  const first=structured.snapshot().blocks[0].id;
  structured.updateBlock(first,{html:'Bottom provider history proof'});
  structured.captureRecovery('w3-d-proof');
  const operational=new W03V34RunsAdapter();
  const session=operational.open(operational.devices[0].id);
  operational.input(session.id,'show status','w3d-runtime-proof-1');
  return {structured,operational,structuredProvider:new StructuredBottomProvider(structured),operationalProvider:new OperationalBottomProvider(operational)};
}

export function runW3DBottomDeepWorkTests(){
  const tests=[];
  test(tests,'w3d.one-global-owner-contract',()=>{const {structuredProvider,operationalProvider}=fixture(),owner=new BottomDeepWorkOwner({providers:[structuredProvider,operationalProvider]});assert(owner.owner===BOTTOM_DEEP_WORK_OWNER&&owner.contract===BOTTOM_DEEP_WORK_CONTRACT&&owner.providerDescriptors().length===2)});
  test(tests,'w3d.real-structured-operational-providers',()=>{const {structuredProvider,operationalProvider}=fixture(),s=validateBottomDeepWorkProvider(structuredProvider),o=validateBottomDeepWorkProvider(operationalProvider);assert(s.family==='structured'&&s.sourceOwner==='StructuredTransactionHistoryRecoveryOwner');assert(o.family==='operational'&&o.sourceOwner==='InternalSimulationAdapter')});
  test(tests,'w3d.open-close-toggle-lifecycle',()=>{const {structuredProvider,operationalProvider}=fixture(),owner=new BottomDeepWorkOwner({providers:[structuredProvider,operationalProvider]});assert(!owner.snapshot().open);owner.open('structured.history-recovery');assert(owner.snapshot().open);owner.toggle();assert(!owner.snapshot().open);owner.toggle('operational.runtime-session');assert(owner.snapshot().open&&owner.snapshot().activeProviderId==='operational.runtime-session');owner.close();assert(!owner.snapshot().open)});
  test(tests,'w3d.closed-inert-state',()=>{const {structuredProvider}=fixture(),owner=new BottomDeepWorkOwner({providers:[structuredProvider]});let p=owner.snapshot().presentation;assert(p.hidden&&p.inert&&!p.interactive&&p.ariaHidden==='true');owner.open();p=owner.snapshot().presentation;assert(!p.hidden&&!p.inert&&p.interactive&&p.ariaHidden==='false');owner.close();p=owner.snapshot().presentation;assert(p.hidden&&p.inert&&!p.interactive)});
  test(tests,'w3d.deterministic-focus-entry-return',()=>{const {structuredProvider,operationalProvider}=fixture(),events=[],invoker={id:'invoker'},bridge={captureCurrent:()=>invoker,enter:id=>{events.push('enter:'+id);return true},restore:target=>{events.push('restore:'+target?.id);return target===invoker}},owner=new BottomDeepWorkOwner({providers:[structuredProvider,operationalProvider],focusBridge:bridge});owner.open('structured.history-recovery');owner.switchProvider('operational.runtime-session');owner.close();assert(events.join('|')==='enter:structured.history-recovery|enter:operational.runtime-session|restore:invoker')});
  test(tests,'w3d.provider-switch-no-state-leakage',()=>{const {structured,operational,structuredProvider,operationalProvider}=fixture(),owner=new BottomDeepWorkOwner({providers:[structuredProvider,operationalProvider]}),beforeStructured=JSON.stringify({tx:structured.transactionDescriptor(),history:structured.historyProjection(),recovery:structured.listRecovery()}),beforeOperational=JSON.stringify({sessions:[...operational.sessions.values()],events:operational.events,devices:operational.devices,run:operational.run});owner.open('structured.history-recovery');owner.switchProvider('operational.runtime-session');owner.switchProvider('structured.history-recovery');owner.close();assert(JSON.stringify({tx:structured.transactionDescriptor(),history:structured.historyProjection(),recovery:structured.listRecovery()})===beforeStructured);assert(JSON.stringify({sessions:[...operational.sessions.values()],events:operational.events,devices:operational.devices,run:operational.run})===beforeOperational)});
  test(tests,'w3d.global-owner-does-not-own-provider-content',()=>{const {structured,structuredProvider,operationalProvider}=fixture(),owner=new BottomDeepWorkOwner({providers:[structuredProvider,operationalProvider]});owner.open('structured.history-recovery');const shell=owner.snapshot(),before=owner.readActiveProvider();assert(!('history' in shell)&&!('events' in shell)&&!('sessions' in shell)&&before.sourceOwner==='StructuredTransactionHistoryRecoveryOwner');const first=structured.snapshot().blocks[0].id;structured.updateBlock(first,{html:'live projection changed after owner construction'});const after=owner.readActiveProvider();assert(after.historyLength===before.historyLength+1)});
  test(tests,'w3d.central-policy-reaches-both-providers',()=>{const {structuredProvider,operationalProvider}=fixture(),probe={...BOTTOM_DEEP_WORK_LIFECYCLE_POLICY,revision:'bottom-deep-work-w3d-policy-probe'},owner=new BottomDeepWorkOwner({providers:[structuredProvider,operationalProvider],policy:probe});owner.open('structured.history-recovery');assert(owner.snapshot().policyRevision===probe.revision);owner.switchProvider('operational.runtime-session');assert(owner.snapshot().policyRevision===probe.revision);owner.close();assert(owner.snapshot().presentation.inert===probe.closed.inert)});
  test(tests,'w3d.no-provider-content-stores-on-global-owner',()=>{const {structuredProvider,operationalProvider}=fixture(),owner=new BottomDeepWorkOwner({providers:[structuredProvider,operationalProvider]});for(const key of ['history','recovery','events','sessions','runtime','terminal','analysis','records','transactions'])assert(!(key in owner),`global owner leaked ${key}`);assert(!('history' in structuredProvider)&&!('recovery' in structuredProvider)&&!('events' in operationalProvider)&&!('sessions' in operationalProvider))});
  test(tests,'w3d.negative-mutation-provider-rejected',()=>{const bad={descriptor:()=>({contract:{id:'BottomDeepWorkProviderContract'},id:'bad',family:'structured',sourceOwner:'x',readOnly:true,ownsCanonicalContent:false}),read:()=>({providerId:'bad',sourceOwner:'x',readOnly:true,ownsCanonicalContent:false}),undo:()=>true};throws(()=>validateBottomDeepWorkProvider(bad),'BOTTOM_PROVIDER_MUTATION_METHOD_FORBIDDEN:undo')});
  test(tests,'w3d.bounded-actions-only',()=>{const {structuredProvider}=fixture(),owner=new BottomDeepWorkOwner({providers:[structuredProvider]});throws(()=>owner.executeAction('history.undo'),'BOTTOM_ACTION_OUT_OF_SCOPE');throws(()=>owner.executeAction('runtime.input'),'BOTTOM_ACTION_OUT_OF_SCOPE')});
  test(tests,'w3d.projections-are-source-truth-not-fabricated',()=>{const {structured,operational,structuredProvider,operationalProvider}=fixture(),sp=structuredProvider.read(),op=operationalProvider.read();assert(sp.historyLength===structured.transactionDescriptor().historyLength&&same(sp.recovery,structured.listRecovery()));assert(same(op.events,operational.recorded().events)&&same(op.sourceEvents,operational.recorded().sourceEvents)&&same(op.devices,operational.recorded().devices))});
  test(tests,'w3d.provider-switch-preserves-provider-specific-state',()=>{const {structuredProvider,operationalProvider}=fixture();structuredProvider.localPresentation={filter:'all'};operationalProvider.localPresentation={selectedSession:'sim-session-1'};const owner=new BottomDeepWorkOwner({providers:[structuredProvider,operationalProvider]});owner.open('structured.history-recovery');owner.switchProvider('operational.runtime-session');owner.switchProvider('structured.history-recovery');assert(structuredProvider.localPresentation.filter==='all'&&operationalProvider.localPresentation.selectedSession==='sim-session-1')});
  test(tests,'w3d.focus.invoker-success-stops-chain',()=>{const {structuredProvider}=fixture(),invoker={id:'invoker'},captured={id:'captured'},fallback={id:'fallback'},events=[],owner=new BottomDeepWorkOwner({providers:[structuredProvider],focusBridge:{captureCurrent:()=>captured,restore:target=>{events.push('restore:'+target.id);return target===invoker},fallback:()=>{events.push('fallback.resolve');return fallback}}});owner.open('structured.history-recovery',{invoker});const receipt=owner.close().lastTransition;assert(receipt.restored&&receipt.returnKind==='invoker');assert(events.join('|')==='restore:invoker');assert(receipt.focusReturn.attempts.length===1&&receipt.focusReturn.attempts[0].kind==='invoker'&&receipt.focusReturn.attempts[0].succeeded)});
  test(tests,'w3d.focus.invoker-fails-fallback-succeeds',()=>{const {structuredProvider}=fixture(),invoker={id:'invoker'},fallback={id:'fallback'},events=[],owner=new BottomDeepWorkOwner({providers:[structuredProvider],focusBridge:{captureCurrent:()=>null,restore:target=>{events.push('restore:'+target.id);return target===fallback},fallback:()=>{events.push('fallback.resolve');return fallback}}});owner.open('structured.history-recovery',{invoker});const receipt=owner.close().lastTransition;assert(receipt.restored&&receipt.returnKind==='fallback');assert(events.join('|')==='restore:invoker|fallback.resolve|restore:fallback');assert(receipt.focusReturn.attempts.map(x=>`${x.kind}:${x.attempted}:${x.succeeded}`).join('|')==='invoker:true:false|captured:false:false|fallback:true:true')});
  test(tests,'w3d.focus.invoker-unavailable-captured-succeeds',()=>{const {structuredProvider}=fixture(),captured={id:'captured'},events=[],owner=new BottomDeepWorkOwner({providers:[structuredProvider],focusBridge:{captureCurrent:()=>captured,restore:target=>{events.push('restore:'+target.id);return target===captured},fallback:()=>{events.push('fallback.resolve');return {id:'fallback'}}}});owner.open('structured.history-recovery');const receipt=owner.close().lastTransition;assert(receipt.restored&&receipt.returnKind==='captured');assert(events.join('|')==='restore:captured');assert(receipt.focusReturn.attempts.map(x=>x.kind).join('|')==='invoker|captured'&&receipt.focusReturn.attempts[0].attempted===false&&receipt.focusReturn.attempts[1].succeeded)});
  test(tests,'w3d.focus.captured-fails-fallback-succeeds',()=>{const {structuredProvider}=fixture(),captured={id:'captured'},fallback={id:'fallback'},events=[],owner=new BottomDeepWorkOwner({providers:[structuredProvider],focusBridge:{captureCurrent:()=>captured,restore:target=>{events.push('restore:'+target.id);return target===fallback},fallback:()=>fallback}});owner.open('structured.history-recovery');const receipt=owner.close().lastTransition;assert(receipt.restored&&receipt.returnKind==='fallback');assert(events.join('|')==='restore:captured|restore:fallback');assert(receipt.focusReturn.attempts.map(x=>`${x.kind}:${x.succeeded}`).join('|')==='invoker:false|captured:false|fallback:true')});
  test(tests,'w3d.focus.all-targets-fail-truthful-receipt',()=>{const {structuredProvider}=fixture(),invoker={id:'invoker'},captured={id:'captured'},fallback={id:'fallback'},events=[],owner=new BottomDeepWorkOwner({providers:[structuredProvider],focusBridge:{captureCurrent:()=>captured,restore:target=>{events.push('restore:'+target.id);return false},fallback:()=>fallback}});owner.open('structured.history-recovery',{invoker});const receipt=owner.close().lastTransition;assert(!receipt.restored&&receipt.returnKind==='none');assert(events.join('|')==='restore:invoker|restore:captured|restore:fallback');assert(receipt.focusReturn.attempts.every(x=>x.attempted&&x.succeeded===false));assert(receipt.focusReturn.restored===false)});
  test(tests,'w3d.focus.restore-throw-continues-to-fallback',()=>{const {structuredProvider}=fixture(),invoker={id:'invoker'},fallback={id:'fallback'},owner=new BottomDeepWorkOwner({providers:[structuredProvider],focusBridge:{captureCurrent:()=>null,restore:target=>{if(target===invoker)throw Error('DETACHED_TARGET');return target===fallback},fallback:()=>fallback}});owner.open('structured.history-recovery',{invoker});const receipt=owner.close().lastTransition;assert(receipt.restored&&receipt.returnKind==='fallback');assert(receipt.focusReturn.attempts[0].error==='DETACHED_TARGET'&&receipt.focusReturn.attempts.at(-1).succeeded)});
  test(tests,'w3d.focus.structured-close-fallback-chain',()=>{const {structuredProvider,operationalProvider}=fixture(),invoker={id:'structured-invoker'},fallback={id:'fallback'},owner=new BottomDeepWorkOwner({providers:[structuredProvider,operationalProvider],focusBridge:{captureCurrent:()=>null,restore:target=>target===fallback,fallback:()=>fallback}});owner.open('structured.history-recovery',{invoker});const receipt=owner.close({reason:'structured-close'}).lastTransition;assert(receipt.activeProviderId==='structured.history-recovery'&&receipt.restored&&receipt.returnKind==='fallback'&&owner.snapshot().presentation.inert)});
  test(tests,'w3d.focus.operational-close-fallback-chain',()=>{const {structuredProvider,operationalProvider}=fixture(),invoker={id:'operational-invoker'},fallback={id:'fallback'},owner=new BottomDeepWorkOwner({providers:[structuredProvider,operationalProvider],focusBridge:{captureCurrent:()=>null,restore:target=>target===fallback,fallback:()=>fallback}});owner.open('operational.runtime-session',{invoker});const receipt=owner.close({reason:'operational-close'}).lastTransition;assert(receipt.activeProviderId==='operational.runtime-session'&&receipt.restored&&receipt.returnKind==='fallback'&&owner.snapshot().presentation.inert)});
  test(tests,'w3d.focus.provider-switch-preserves-return-chain',()=>{const {structuredProvider,operationalProvider}=fixture(),invoker={id:'invoker'},captured={id:'captured'},events=[],owner=new BottomDeepWorkOwner({providers:[structuredProvider,operationalProvider],focusBridge:{captureCurrent:()=>captured,enter:id=>{events.push('enter:'+id);return true},restore:target=>{events.push('restore:'+target.id);return target===captured},fallback:()=>({id:'fallback'})}});owner.open('structured.history-recovery',{invoker});owner.switchProvider('operational.runtime-session');const receipt=owner.close({reason:'after-switch'}).lastTransition;assert(receipt.activeProviderId==='operational.runtime-session'&&receipt.returnKind==='captured'&&receipt.restored);assert(events.join('|')==='enter:structured.history-recovery|enter:operational.runtime-session|restore:invoker|restore:captured')});
  test(tests,'w3d.focus.toggle-close-uses-fallback-chain',()=>{const {structuredProvider}=fixture(),invoker={id:'invoker'},fallback={id:'fallback'},owner=new BottomDeepWorkOwner({providers:[structuredProvider],focusBridge:{captureCurrent:()=>null,restore:target=>target===fallback,fallback:()=>fallback}});owner.toggle('structured.history-recovery',{invoker});const closed=owner.toggle('structured.history-recovery');assert(!closed.open&&closed.presentation.inert&&closed.lastTransition.restored&&closed.lastTransition.returnKind==='fallback')});
  return tests;
}
